import{_ as e,o as s,c as n,a2 as t}from"./chunks/framework.EUByU7Iq.js";const u=JSON.parse('{"title":"第四章 非法人组织","description":"","frontmatter":{"title":"第四章 非法人组织","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/disizhang：feifarenzuzhi.md","filePath":"blogs/CC/第四章：非法人组织.md"}'),i={name:"blogs/CC/disizhang：feifarenzuzhi.md"};function r(l,a,o,p,d,h){return s(),n("div",null,[...a[0]||(a[0]=[t(`<h3 id="第一百零二条" tabindex="-1">第一百零二条 <a class="header-anchor" href="#第一百零二条" aria-label="Permalink to &quot;第一百零二条&quot;">​</a></h3><p>非法人组织是不具有法人资格，但是能够依法以自己的名义从事民事活动的组织。 非法人组织包括个人独资企业、合伙企业、不具有法人资格的专业服务机构等。</p><h3 id="第一百零三条" tabindex="-1">第一百零三条 <a class="header-anchor" href="#第一百零三条" aria-label="Permalink to &quot;第一百零三条&quot;">​</a></h3><p>非法人组织应当依照法律的规定登记。 设立非法人组织，法律、行政法规规定须经有关机关批准的，依照其规定。</p><h3 id="第一百零四条" tabindex="-1">第一百零四条 <a class="header-anchor" href="#第一百零四条" aria-label="Permalink to &quot;第一百零四条&quot;">​</a></h3><p>非法人组织的财产不足以清偿债务的，其出资人或者设立人承担无限责任。法律另有规定的，依照其规定。</p><h3 id="第一百零五条" tabindex="-1">第一百零五条 <a class="header-anchor" href="#第一百零五条" aria-label="Permalink to &quot;第一百零五条&quot;">​</a></h3><p>非法人组织可以确定一人或者数人代表该组织从事民事活动。</p><h3 id="第一百零六条" tabindex="-1">第一百零六条 <a class="header-anchor" href="#第一百零六条" aria-label="Permalink to &quot;第一百零六条&quot;">​</a></h3><p>有下列情形之一的，非法人组织解散：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>（一）章程规定的存续期间届满或者章程规定的其他解散事由出现；</span></span>
<span class="line"><span>（二）出资人或者设立人决定解散；</span></span>
<span class="line"><span>（三）法律规定的其他情形。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="第一百零七条" tabindex="-1">第一百零七条 <a class="header-anchor" href="#第一百零七条" aria-label="Permalink to &quot;第一百零七条&quot;">​</a></h3><p>非法人组织解散的，应当依法进行清算。</p><h3 id="第一百零八条" tabindex="-1">第一百零八条 <a class="header-anchor" href="#第一百零八条" aria-label="Permalink to &quot;第一百零八条&quot;">​</a></h3><p>非法人组织除适用本章规定外，参照适用本编第三章第一节的有关规定。</p>`,15)])])}const b=e(i,[["render",r]]);export{u as __pageData,b as default};
